lucide.createIcons();

// State
let tasks = [
  {
    id: "1",
    text: "Design new dashboard layout",
    completed: false,
    priority: "high",
  },
  {
    id: "2",
    text: "Review team pull requests",
    completed: true,
    priority: "medium",
  },
  {
    id: "3",
    text: "Update project documentation",
    completed: false,
    priority: "low",
  },
  {
    id: "4",
    text: "Schedule weekly team meeting",
    completed: false,
    priority: "medium",
  },
  {
    id: "5",
    text: "Fix navigation bug in mobile view",
    completed: false,
    priority: "high",
  },
];

let currentFilter = "all";

// DOM elements
const taskList = document.getElementById("taskList");
const emptyState = document.getElementById("emptyState");
const taskInput = document.getElementById("taskInput");
const taskPriority = document.getElementById("taskPriority");
const addBtn = document.getElementById("addTaskBtn");
const emptyAddBtn = document.getElementById("emptyAddBtn");
const clearCompletedBtn = document.getElementById("clearCompletedBtn");
const selectAllBtn = document.getElementById("selectAllBtn");
const filterBtns = document.querySelectorAll(".filter-btn");

// Stats elements
const totalTasksSpan = document.getElementById("totalTasks");
const completedTasksSpan = document.getElementById("completedTasks");
const pendingTasksSpan = document.getElementById("pendingTasks");

// Set current date
document.getElementById("currentDate").textContent =
  new Date().toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });

// Helper: escape HTML
const escapeHtml = (text) => {
  const div = document.createElement("div");
  div.textContent = text;
  return div.innerHTML;
};

// Update stats
const updateStats = () => {
  const total = tasks.length;
  const completed = tasks.filter((t) => t.completed).length;
  const pending = total - completed;

  totalTasksSpan.textContent = total;
  completedTasksSpan.textContent = completed;
  pendingTasksSpan.textContent = pending;
};

// Filter tasks
const getFilteredTasks = () => {
  switch (currentFilter) {
    case "active":
      return tasks.filter((t) => !t.completed);
    case "completed":
      return tasks.filter((t) => t.completed);
    default:
      return tasks;
  }
};

// Render tasks
const renderTasks = () => {
  const filteredTasks = getFilteredTasks();

  if (filteredTasks.length === 0) {
    taskList.classList.add("hidden");
    emptyState.classList.remove("hidden");
    lucide.createIcons();
    updateStats();
    return;
  }

  taskList.classList.remove("hidden");
  emptyState.classList.add("hidden");

  let html = "";
  filteredTasks.forEach((task) => {
    const priorityColors = {
      low: "bg-blue-50 text-blue-700 border-blue-200",
      medium: "bg-orange-50 text-orange-700 border-orange-200",
      high: "bg-red-50 text-red-700 border-red-200",
    };

    html += `
                    <div class="task-item" data-id="${task.id}">
                        <input 
                            type="checkbox" 
                            class="shadcn-checkbox task-checkbox" 
                            ${task.completed ? "checked" : ""}
                            data-id="${task.id}"
                        >
                        <span class="flex-1 text-sm ${task.completed ? "text-muted-foreground line-through" : "text-foreground"}">
                            ${escapeHtml(task.text)}
                        </span>
                        <span class="w-20">
                            <span class="text-xs px-2 py-1 rounded-full border ${priorityColors[task.priority]}">
                                ${task.priority}
                            </span>
                        </span>
                        <span class="w-20">
                            <span class="text-xs ${task.completed ? "text-green-600" : "text-orange-500"}">
                                ${task.completed ? "Completed" : "Pending"}
                            </span>
                        </span>
                        <button class="delete-button" data-id="${task.id}">
                            <i data-lucide="x" class="w-4 h-4"></i>
                        </button>
                    </div>
                `;
  });

  taskList.innerHTML = html;
  lucide.createIcons();
  attachTaskEvents();
  updateStats();
};

// Attach events to checkboxes and delete buttons
const attachTaskEvents = () => {
  document.querySelectorAll(".task-checkbox").forEach((checkbox) => {
    checkbox.addEventListener("change", (e) => {
      const id = e.target.dataset.id;
      const task = tasks.find((t) => t.id === id);
      if (task) {
        task.completed = e.target.checked;
        renderTasks();
      }
    });
  });

  document.querySelectorAll(".delete-button").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      const id = e.currentTarget.dataset.id;
      tasks = tasks.filter((t) => t.id !== id);
      renderTasks();
    });
  });
};

// Add new task
const addTask = () => {
  const text = taskInput.value.trim();
  if (!text) {
    taskInput.classList.add("border-destructive");
    setTimeout(() => taskInput.classList.remove("border-destructive"), 500);
    return;
  }

  const newTask = {
    id: Date.now().toString(),
    text: text,
    completed: false,
    priority: taskPriority.value,
  };

  tasks.push(newTask);
  renderTasks();
  taskInput.value = "";
  taskInput.focus();
};

// Clear completed tasks
const clearCompleted = () => {
  tasks = tasks.filter((t) => !t.completed);
  renderTasks();
};

// Toggle select all
const toggleSelectAll = () => {
  const filteredTasks = getFilteredTasks();
  const allCompleted = filteredTasks.every((t) => t.completed);

  filteredTasks.forEach((task) => {
    const originalTask = tasks.find((t) => t.id === task.id);
    if (originalTask) {
      originalTask.completed = !allCompleted;
    }
  });

  renderTasks();
};

// Filter event listeners
filterBtns.forEach((btn) => {
  btn.addEventListener("click", () => {
    filterBtns.forEach((b) => b.classList.remove("active"));
    btn.classList.add("active");
    currentFilter = btn.dataset.filter;
    renderTasks();
  });
});

// Event listeners
addBtn.addEventListener("click", addTask);
emptyAddBtn.addEventListener("click", addTask);
taskInput.addEventListener("keypress", (e) => {
  if (e.key === "Enter") addTask();
});

clearCompletedBtn.addEventListener("click", clearCompleted);
selectAllBtn.addEventListener("click", toggleSelectAll);

// Initial render
renderTasks();
